// rox shader: Phosphor. The Tube preset forked into this workspace's own
// screen, since a green-on-black terminal wants the whole glass and not just
// a curved face.
//
// Everything the preset did is still here: the fill-normalized barrel warp,
// scanlines off the device rows, a little misconvergence at the edges, a
// vignette toward the rim. What the fork adds is the phosphor itself. The
// picture is pushed into one glowing colour with a white-hot core, the lit
// pixels bleed into the glass around them, a grille rules the picture into
// stripes every four device pixels, and the last frame is kept under this
// one so moving pixels trail the way a coated tube smears.
//
// The grille and the lines are measured in device pixels, so both go finer
// as the display does. On a 2x screen they're a texture rather than the
// stripes they read as at 1x; that's the knobs' problem to answer, not
// something the shader can work out, since nothing in the uniforms says
// what the scale factor is.
//
// The slots are the tube's dimensions rather than a response to the music.
// There's no signal pool in this workspace, so all ten are hand-set and the
// bundle ships the tuning; route them from another look's pool and the tube
// moves. Hue is the one worth playing with: 0 is P1 green, around 0.2 is
// amber, and the rest of the wheel is there because a tube with a hue knob
// beats one without.
//
// The sweep is the only slot that reads anything on its own, and only
// because it has to. See the note on it below.
//
// Every slot rests at a mild tube, so a fresh route reading zero is still a
// look rather than a blank screen.
//
// The afterglow is why this one asks for idle frames. `prev` has to keep
// being drawn to burn out, and a pass that stopped when the music did would
// park a ghost on screen instead.
//
// @overlay
// @slot 0: bend
// @slot 1: lines
// @slot 2: fringe
// @slot 3: rim
// @slot 4: hue
// @slot 5: tint
// @slot 6: glow
// @slot 7: grille
// @slot 8: afterglow
// @slot 9: sweep

const PHOS_TAU: f32 = 6.28318530718;
const PHOS_LUMA: vec3<f32> = vec3<f32>(0.2126, 0.7152, 0.0722);

// Barrel warp normalized on the edge midpoints, where dot(c, c) is 0.25.
//
// The preset normalizes on the corners instead, which fills the window with
// no dead border but magnifies everything between the corners, and what it
// magnifies off the top is the menu bar. Normalizing on the midpoints is the
// other trade: every pixel of the frame stays on the glass, and the corners
// are what run past its edge instead. `glass` below is what cuts them.
fn phos_warp(uv: vec2<f32>, bend: f32) -> vec2<f32> {
    let c = uv - 0.5;
    return 0.5 + c * ((1.0 + bend * dot(c, c)) / (1.0 + bend * 0.25));
}

// The coating, as a colour. Peak channel normalized to 1 so the hue knob
// changes which phosphor this is and never how bright it burns.
fn phos_tint(hue: f32) -> vec3<f32> {
    let raw = 0.5 + 0.5 * cos(PHOS_TAU * (hue + vec3<f32>(0.67, 0.0, 0.33)));
    return raw / max(max(raw.r, raw.g), max(raw.b, 0.001));
}

fn phos_luma(rgb: vec3<f32>) -> f32 {
    return dot(rgb, PHOS_LUMA);
}

fn phos_read(uv: vec2<f32>) -> vec3<f32> {
    return textureSampleLevel(screen, samp, clamp(uv, vec2<f32>(0.0), vec2<f32>(1.0)), 0.0).rgb;
}

fn fs_user(uv: vec2<f32>) -> vec4<f32> {
    let bend = 0.10 + 0.35 * clamp(params.signals[0].x, 0.0, 1.0);
    let lines = 0.08 + 0.30 * clamp(params.signals[0].y, 0.0, 1.0);
    let spread = clamp(params.signals[0].z, 0.0, 1.0);
    let rim = 0.25 + 0.45 * clamp(params.signals[0].w, 0.0, 1.0);
    let hue = params.signals[1].x;
    let tint_amount = 0.35 + 0.65 * clamp(params.signals[1].y, 0.0, 1.0);
    let glow = 0.20 + 0.80 * clamp(params.signals[1].z, 0.0, 1.0);
    let grille = 0.10 + 0.60 * clamp(params.signals[1].w, 0.0, 1.0);
    let afterglow = clamp(params.signals[2].x, 0.0, 1.0);
    let line_amount = clamp(params.signals[2].y, 0.0, 1.0);

    let res = max(params.resolution, vec2<f32>(1.0));
    // How bright the page under the tube already is, off the palette's own
    // background. A dark theme is a tube in a dark room and gets the whole
    // effect; a light one is mostly lit paper, where a colour wash, a
    // halation firing on everything and a full-strength mesh over the
    // brightest thing on screen would only make it unreadable. So the
    // coating, the bleed, the grille and the lines all come off with it,
    // and the geometry - the bend, the fringe, the rim - stays put.
    let page = clamp(params.user_meta[1].x, 0.0, 1.0);
    let ink = 1.0 - page;
    let room = 0.35 + 0.65 * ink;
    let fringe = (0.6 + 2.4 * spread) / res.x;

    var w = phos_warp(uv, bend);

    // The sweep: one row crossing the glass slowly, pinching the picture
    // sideways as it passes and lighting nothing. It's a line you read off
    // what it does to the text, not off any glow of its own. Its width is
    // device pixels rather than a fraction of the window, so it stays a line
    // on a big window instead of growing into a band.
    //
    // It's gated on the play flag deliberately. This pass's clock only
    // advances while the signal feed pushes, so a line travelling on
    // params.time alone would stop dead mid-screen the moment the music did;
    // riding the flag means it fades out instead of parking.
    let sweep = line_amount * clamp(params.user_meta[0].z, 0.0, 1.0);
    // Distance from the line in device pixels, wrapped. Positive is below
    // the line, which is where it hasn't reached yet.
    let dy = (fract(w.y - fract(params.time * 0.073) + 0.5) - 0.5) * res.y;
    // Zero on the line itself, hardest two pixels out either side and gone
    // by four: the picture is pulled one way ahead of it and the other way
    // behind, over a band thin enough to read as one bad row.
    let pinch = clamp(dy / 4.0, -1.0, 1.0);
    w.x = w.x + pinch * (1.0 - abs(pinch)) * 4.0 * sweep * 8.0 / res.x;

    // Where the sampling point has run off the frame: the corners the bend
    // pushes past the edge, and the couple of pixels the sweep shoves past
    // the sides. Cut rather than clamped, since a clamp smears the last row
    // of pixels outward and reads as a stretch mark. Feathered over a pixel
    // so the corner comes out as a curve rather than a staircase.
    let edge = min(min(w.x, 1.0 - w.x) * res.x, min(w.y, 1.0 - w.y) * res.y);
    let glass = smoothstep(-1.0, 1.0, edge);
    let wc = clamp(w, vec2<f32>(0.0), vec2<f32>(1.0));

    // The fringe: red and blue pulled apart a pixel or three, green read
    // straight, the way a misconverged tube smears its edges. Three taps,
    // used twice: as the picture's own colour, and as the three brightnesses
    // the coating lights from, so the misconvergence survives being pushed
    // into one phosphor instead of averaging itself away.
    let tap_r = phos_read(wc + vec2<f32>(fringe, 0.0));
    let tap_c = phos_read(wc);
    let tap_b = phos_read(wc - vec2<f32>(fringe, 0.0));
    var rgb = vec3<f32>(tap_r.r, tap_c.g, tap_b.b);

    // Into the coating: one colour carrying the picture's own brightness,
    // burning toward white only where the beam is hardest. That highlight is
    // what keeps the accent from flattening into the body text.
    let tint = phos_tint(hue);
    let lum = phos_luma(tap_c);
    let beam = vec3<f32>(
        tint.r * phos_luma(tap_r),
        tint.g * lum,
        tint.b * phos_luma(tap_b),
    );
    let phos = min(beam + vec3<f32>(pow(lum, 5.0) * 0.30), vec3<f32>(1.0));
    rgb = mix(rgb, phos, tint_amount * room);

    // Halation: what's lit bleeds into the glass around it. Two rings of
    // taps off the composed frame, gated on the neighbourhood's brightness
    // so unlit chrome stays where it is.
    var halo = 0.0;
    for (var i = 0u; i < 6u; i = i + 1u) {
        let a = f32(i) * 1.04719755;
        let dir = vec2<f32>(cos(a), sin(a)) / res;
        halo = halo + phos_luma(phos_read(wc + dir * 3.0));
        halo = halo + phos_luma(phos_read(wc + dir * 8.0));
    }
    halo = halo / 12.0;
    rgb = rgb + tint * smoothstep(0.06, 0.45, halo) * glow * ink * 0.35;

    // The grille: a stripe every four device pixels, swinging around one so
    // turning it up textures the picture instead of dimming it. Brightness
    // only, deliberately. Splitting the stripes into RGB the way a colour
    // tube's mask does pulls saturated text toward white, which is the one
    // thing a single-phosphor screen never does.
    let stripe = 0.5 + 0.5 * cos(PHOS_TAU * wc.x * res.x / 4.0);
    rgb = rgb * mix(1.0, stripe * 2.0, grille * room);

    // Scanlines on the warped rows so they bow with the face, normalized the
    // same way the grille is, and a slow soft flicker off the clock the way
    // mains ripple shows on a real one.
    let row = wc.y * res.y;
    let depth = lines * room;
    let scan = (1.0 - depth * (0.5 + 0.5 * sin(row * 2.09439510))) / (1.0 - depth * 0.5);
    let flicker = 1.0 + 0.012 * sin(params.time * 9.0);
    rgb = rgb * scan * flicker;

    // Vignette toward the rim, and the glass cut off the sampling point.
    let shade = 1.0 - rim * smoothstep(0.5, 1.4, length((uv - 0.5) * 2.0));
    rgb = clamp(rgb * shade * glass, vec3<f32>(0.0), vec3<f32>(1.0));

    // Afterglow. The last frame is kept under this one rather than blended
    // into it: a still page decays to less than itself and comes out exactly
    // itself, so only pixels that actually moved leave a trail.
    //
    // The cap is load-bearing, and the reason is the clock. This pass's
    // clock advances on the signal feed, not on frames, so an app sitting
    // idle draws frame after frame with the same `delta` - and on the very
    // first tick that delta is zero. A decay written per second alone would
    // then be a decay of exactly nothing, and every frame would max() into
    // the last one until the window was a solid burn of everything that had
    // ever been on it. So the ghost also has to lose a fixed share per
    // frame, whatever the clock says it is.
    let step = clamp(params.delta, 0.0, 0.1);
    let keep = min(exp2(-step / (0.015 + 0.25 * afterglow)), 0.86);
    let ghost = textureSampleLevel(prev, samp, uv, 0.0).rgb * keep;
    return vec4<f32>(max(rgb, ghost), 1.0);
}
